package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.JsonSerializable;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.util.RawValue;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class POJONode_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        Object pojo = new Object();
        POJONode node = new POJONode(pojo);
        // Covers: if (o == this) return true;
        assertTrue(node.equals(node));
    }

    @Test
    public void testEquals_Null() {
        POJONode node = new POJONode(new Object());
        // Covers: if (o == null) return false;
        assertFalse(node.equals(null));
    }

    @Test
    public void testEquals_DifferentType() {
        POJONode node = new POJONode(new Object());
        String other = "not a POJONode";
        // Covers: if (o instanceof POJONode) -> false, return false;
        assertFalse(node.equals(other));
    }

    @Test
    public void testEquals_SamePojo_Success() {
        // This test relies on the internal _pojoEquals implementation.
        // Since we cannot mock the protected _pojoEquals easily without a subclass,
        // we use a standard POJO that implements equals correctly.
        class TestPojo {
            private final int val;
            TestPojo(int val) { this.val = val; }
            @Override
            public boolean equals(Object o) {
                if (this == o) return true;
                if (o == null || getClass() != o.getClass()) return false;
                TestPojo testPojo = (TestPojo) o;
                return val == testPojo.val;
            }
            @Override
            public int hashCode() { return Integer.hashCode(val); }
        }

        TestPojo p1 = new TestPojo(1);
        TestPojo p2 = new TestPojo(1);
        TestPojo p3 = new TestPojo(2);

        POJONode node1 = new POJONode(p1);
        POJONode node2 = new POJONode(p2);
        POJONode node3 = new POJONode(p3);

        // Covers: if (o instanceof POJONode) -> true, calling _pojoEquals
        assertTrue(node1.equals(node2));
        assertFalse(node1.equals(node3));
    }

    @Test
    public void testEquals_SubclassOfPOJONode() {
        // Test that the instanceof check works as expected for subclasses
        class SubPOJONode extends POJONode {
            public SubPOJONode(Object v) { super(v); }
        }

        POJONode node = new POJONode(new Object());
        SubPOJONode subNode = new SubPOJONode(new Object());

        // instanceof POJONode will be true for SubPOJONode
        // This will trigger _pojoEquals
        assertFalse(node.equals(subNode));
    }
}
